package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/intake") class IntakeController {private final IntakeService service;private final TenantService tenants;IntakeController(IntakeService s,TenantService t){service=s;tenants=t;}private Membership member(Authentication a,String org){return tenants.membership(UUID.fromString(a.getName()),org);}@GetMapping List<IntakeJobResponse> list(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.jobs(member(a,org));}@PostMapping(value="/csv",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) IntakeJobResponse upload(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@RequestPart("file") MultipartFile file){return service.uploadCsv(member(a,org),file);}@PostMapping("/{id}/confirm") IntakeJobResponse confirm(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody ConfirmIntakeRequest request){return service.confirm(member(a,org),id,request);}@PatchMapping("/{jobId}/lines/{lineId}/resolution") IntakeJobResponse resolve(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID jobId,@PathVariable UUID lineId,@Valid @RequestBody ResolveIntakeLineRequest request){return service.resolve(member(a,org),jobId,lineId,request);}}
